  'limport.subtitle': 'CSV या Excel — एक लॉट के लिए एक पंक्ति। कुछ भी बनने से पहले हर पंक्ति जाँची जाती है; एक खराब पंक्ति अच्छी पंक्तियों को नहीं रोकती।',
  'limport.trustPath': 'बल्क से बनी लिस्टिंग सामान्य रास्ता ही चलती हैं: ड्राफ़्ट → सदस्य की सहमति → QC → प्रकाशित। बल्क प्रविष्टि तेज़ करता है, भरोसा नहीं छोड़ता — समीक्षक की मंज़ूरी बिना कुछ भी खरीदार तक नहीं जाता।',
  'limport.consentNote': 'हर पंक्ति किसी और की उपज है, इसलिए हर सदस्य की on-behalf सहमति दर्ज होनी चाहिए (आवाज़ या ऐप टैप)। जिनमें नहीं है, वे सुधार के लिए चिह्नित होती हैं — चुपचाप हटाई नहीं जातीं। उनकी उपज, उनकी हाँ।',
  'limport.kycGap': 'कैनन का “KYC बाकी — ड्राफ़्ट ठीक, प्रकाशन सत्यापन तक रुका” जानबूझकर आधा बना है: ड्राफ़्ट बनता है, पर इस प्लेटफ़ॉर्म पर प्रकाशन पर कोई KYC गेट कहीं नहीं है (प्रति-भूमिका KYC मैप भुगतान के लिए है, लिस्टिंग के लिए नहीं)। यहाँ गेट गढ़ना यह नियम केवल आयातित लॉट पर लगाता — इसलिए इसे बैकएंड काम के रूप में नाम दिया, गढ़ा नहीं।',
  'limport.templateHeading': 'टेम्पलेट',
  'limport.templateNote': 'कॉलम: {columns}। इसी सूची से बनता है जिसे इंपोर्टर पढ़ता है, इसलिए टेम्पलेट पार्सर से अलग नहीं हो सकता।',
  'limport.templateRequired': 'सिर्फ़ phone (किसकी उपज) और product (क्या) भरना ज़रूरी है — बाकी की अनुपस्थिति स्वाभाविक है। दाम प्रति इकाई है; unit कॉलम तय करता है कौन-सी। प्रति-क्विंटल शीट पर प्रति-किलो दाम पकड़ा जाता है और सुधार सुझाया जाता है।',
