  'inv.withoutBreakdown': 'इस माह के {n} इनवॉइस उनके टैक्स-विवरण दर्ज होने से पहले जारी हुए थे। वे ऊपर के आँकड़ों में शामिल नहीं हैं और पुनः निकाले नहीं जा सकते — खरीदार की प्रति में वही आँकड़ा है जिसके साथ वे जारी हुए।',
