  // PC-56 TENANT-4a · W143/W144 — the ORGANISATION's wallet and its ledger.
  'wal.title': 'वॉलेट',
  'wal.intro': 'Aapki sanstha ke teen khaate (main · commission · hold), sabhi append-only hash-chained ledger par aadharit. Yahan har aankda aapki apni ledger entries ka jod hai — koi cached balance nahin.',
  'wal.notYourPersonalWallet': 'Yeh sanstha ka paisa hai. Aapka nijee wallet member app mein hai; woh alag khaata hai aur isme kabhi nahin milta.',
  'wal.restricted': 'Sanstha ke balance dekhne ke liye wallet.org_view anumati chahiye. Admin se maangein — ledger par koi asar nahin padta.',
  'wal.loadError': 'Balance load nahin ho paye. Ledger surakshit hai aur payouts samay par chalte hain. Phir se koshish karein.',
  'wal.frozen': 'freeze kiya gaya',
  'wal.account.main': 'main',
  'wal.account.commission': 'commission',
  'wal.account.hold': 'hold',
  'wal.accountMeaning.main': 'Abhi kharch yogya — doodh bill, yojana vitaran aur loan vitaran yahin se diye jaate hain.',
  'wal.accountMeaning.commission': 'Aapki sanstha ka kamaya commission, order poora hone par jama aur refund hone par wapas.',
  'wal.accountMeaning.hold': 'Vivaad ke against roka gaya paisa. Aaj is khaate mein kuch bhi nahin likhta — neeche dekhein.',
  'wal.state.reconciled': 'ledger aur cache sahmat',
  'wal.state.drifted': 'cache asahmat — ledger dikhaya gaya',
  'wal.state.never_used': 'kabhi upyog nahin hua',
  'wal.driftNotice': 'Cached balance {cached} kehta hai, antar {drift}. Upar ka aankda ledger ka apna jod hai, jo asli bahi-khaata hai. Platform reconciliation ise pakdegi; kuch nahin khoya.',
  'wal.holdNoFreezePath': 'Yeh shoonya hai kyunki KOI code path sanstha ka paisa freeze nahin karta. Jab kharidaar vivaad uthata hai, platform uska poora bhugtan escrow mein rakhta hai jab tak vivaad band na ho — aapke wallet par per-line freeze nahin hai.',
  'wal.holdFrozen': 'Yeh khule vivaad ke against roka gaya paisa hai, ledger mein darj.',
  'wal.holdNeverWritten': 'Hold khaate mein ek bhi entry nahin hai — ledger banne ke baad se kabhi likha hi nahin gaya.',
  'wal.gapsTitle': 'Nahin bana — aur naam se kaha gaya, banane ka dhong nahin',
  'wal.gap.add_funds': 'UPI se paisa daalna: platform mein sanstha ke liye top-up abhi kahin nahin hai. Aisa form jo raashi le aur usse bhejne ki jagah na ho, dikhega jaise paisa chala gaya — isliye button nahin hai.',
  'wal.gap.payout_bank_change': 'Payout bank khaata badalna (owner + checker + 24 ghante ka cooling period) nahin bana. Aaj payout khaate vyaktigat sadasyon ke hote hain, KYC se verify. Jab tak control asli na ho, yahan nahin diya jaayega.',
  'wal.gap.tenant_hold_freeze': 'Vivaad ke against bhugtan ka hissa freeze karna nahin bana. Uske badle escrow kharidaar ka poora bhugtan order ke liye rokta hai, aur vivaad wali screen yeh kehti hai.',
  'wal.todayTitle': 'Aaj ki halchal',
  'wal.todayEmpty': 'Aaj sanstha wallet se abhi kuch nahin guzra. Bikri, payout aur fees jaise hote hain waise yahan dikhenge.',
  'wal.healthTitle': 'Ledger ki sehat',
  'wal.health.cached_vs_ledger': 'Aapke cached balance aapki apni entries ke jod se milte hain',
  'wal.health.own_chain': 'Aapke khaate ki hash chain, entry-dar-entry phir se gini gayi',
  'wal.health.platform_recon': 'Poore platform ka zero-sum aur gateway reconciliation',
  'wal.healthState.ok': 'jaancha gaya — theek',
  'wal.healthState.attention': 'dhyaan chahiye',
  'wal.healthState.unverifiable': 'jaancha nahin ja saka',
  'wal.healthState.not_ours_to_assert': 'platform dwara chalaya jaata hai',
  'wal.healthPlatformNote': 'Zero-sum aur gateway reconciliation poore ledger par chalte hain, jo har sanstha saajha karti hai. Platform unhe chalata hai aur unke liye jawabdeh hai; yeh console doosri sansthaon ke paise ke baare mein "0 breaks" nahin dohraayega. Jo yeh jaanchta hai woh upar hai: aapke balance aapki entries ke saath, aur aapki chain.',
  'wal.chain.intact': 'akhand — har entry apne darj maan se milti hai aur har link jud़ta hai',
  'wal.chain.headMismatch': 'chain saaf chalti hai lekin khaate ka head pointer uski antim entry se asahmat hai — platform ko bataayein',
  'wal.chain.hashMismatch': 'ek entry apne darj maan se nahin milti — turant platform ko bataayein',
  'wal.chain.chainBreak': 'ek link pichhli entry se nahin milta — turant platform ko bataayein',
  'wal.chain.incomplete': 'ek baar mein chalne se zyada entries hain, isliye yeh anjaancha hai, akhand nahin',
  'wal.chain.empty': 'abhi koi entry nahin, isliye jaanchne ko kuch nahin',
  'wal.escrowTitle': 'Escrow (platform ke paas, abhi aapka nahin)',
  'wal.escrowHeld': 'Aapke {count} chalte orders ka kharidaar paisa. Delivery pakki hone tak yeh platform escrow mein rehta hai aur aapke balance ka hissa nahin hai. Escrow koi nahin kharchta, hum bhi nahin.',
  'wal.escrowNone': 'Abhi aapke liye koi kharidaar paisa nahin roka gaya hai.',
  'wal.escrowBasis': 'Aadhaar: aapki sanstha ki id waali escrow entries ka net — capture jodte hain, poore hone aur refund ghataate hain. Ledger ka ganit, cached aankda nahin.',
  'wal.openLedger': 'Ledger kholein — har entry',
  'wal.ledgerTitle': 'Wallet len-den',
  'wal.ledgerIntro': 'Ledger, sirf jodne wala: har vyapaar ghatna ek len-den hai jiski entries ka jod shoonya hai. Filter tithi-baddh hain aur default pichhle 30 din.',
  'wal.ledgerEmpty': 'Sanstha wallet se guzarne wali bikri, payout, fees aur refund jaise hote hain waise yahan dikhenge.',
  'wal.ledgerEmptyFiltered': 'Is avadhi mein in filters se koi entry nahin milti. Tithi badhayein ya filter hatayein — ledger das saal rakhta hai, maheene se baanta hua.',
  'wal.ledgerLoadError': 'Ledger view load nahin ho paya. Ledger khud append-only aur surakshit hai. Phir se koshish karein.',
  'wal.filterAccount': 'Khaata',
  'wal.filterAllAccounts': 'Sabhi khaate',
