  'wal.exportCsv': 'CSV nikaalein',
  'wal.exportReady': 'Export taiyaar: {rows} entries, receipt ke saath jisme row ginti, data ka sha256 aur kisne maanga yeh darj hai.',
  'wal.exportBlocked.noPermission': 'Export ke liye wallet.org_view anumati chahiye.',
  'wal.exportBlocked.windowTooWide': 'Export se pehle tithi range chhoti karein — export 366 din tak seemit hai.',
  'wal.exportBlocked.nothingToExport': 'Is avadhi mein nikaalne ko kuch nahin hai.',
  'wal.err.exportTooLarge': 'Is avadhi mein ek file se zyada entries hain. Tithi range chhoti karein — beech maheene ruk jaane wala statement poora samjha jaayega.',
  'wal.err.exportFailed': 'Export nahin ban paya. Kuch darj nahin hua aur kuch nahin badla.',
  'wal.err.windowTooWide': 'Tithiyan 366 din ya usse kam ki sahi range honi chahiye.',
  'wal.colWhen': 'Kab',
  'wal.colTxn': 'Len-den',
  'wal.colType': 'Prakaar',
  'wal.colAccount': 'Khaata',
  'wal.colReference': 'Sandarbh',
  'wal.colAmount': 'Raashi',
  'wal.colBalanceAfter': 'Baad ka balance (us khaate ka)',
  'wal.noEditByDesign': 'Is screen par edit ka control jaan-boojh kar nahin hai. Galti reversal entry se sudhari jaati hai, isliye itihaas poori kahani kehta hai — aur database update se mana kar deta hai chahe koi screen maange.',
  'wal.keysetOnly': 'Page aage-peeche chalte hain, number se nahin: append-only ledger par page number kal kahin aur dikhaayega.',

  // PC-56 TENANT-4b · W145/W146 — the organisation's payout queue and the batch approval gate.
  'po.title': 'Payout',
  'po.intro': 'Aapke sadasyon aur shramikon ko paisa. Order poore hone aur cycle band hone par payout apne aap qatar mein aate hain; ve ek aise batch mein jaate hain jise doosre vyakti ne hastakshar kiya ho.',
  'po.makerCheckerNote': 'Ek vyakti aaj raat ka batch taiyaar karta hai, doosra use manzoor karta hai. Is wave se pehle woh hastakshar kahin nahin tha — ek scheduled job apne aap paisa bhej deta tha.',
