  'po.rule.singleSigner': 'Yeh batch aapki sanstha ki seema {threshold} se neeche hai, isliye ek manzoori kaafi hai — taiyaar karne wale ki bhi. Har batch par do hastakshar chahiye to seema shoonya kar dein.',
