  'po.preUnverifiableNote': '{count} jaanch nahin chal payi kyunki uska srot abhi maujood hi nahin hai — is platform par koi risk desk nahin hai. Unhe tick ki jagah "anjaanchi" dikhaya gaya hai, aur ve aapki manzoori nahin rokti. Jo jaanch VIFAL hoti hai, wah rokti hai.',
