  // PC-56 TENANT-4c · W147/W148 — the settlement cycle and the statements it produces.
  'stl.title': 'Settlement',
  'stl.intro': 'Prati-vikreta settlement cycle: kul bikri − commission − tax = shudh bhugtan. Cycle band karna ek avadhi ke vyapaar ko aise statement mein badalta hai jo aapke sadasya haath mein rakh sakein, aur ismein do log lagte hain.',
  'stl.restricted': 'Settlement cycle ke liye settlement.close anumati chahiye. Admin se maangein — cycle par koi asar nahin.',
  'stl.loadError': 'Cycle load nahin ho paya. Avadhi mein kuch nahin badla. Phir koshish karein.',
  'stl.noCycle': 'Abhi koi cycle khula nahin. Jaise hi pehli bikri iski avadhi mein nipatti hai, cycle khul jaata hai.',
  'stl.currentCycle': 'Vartamaan cycle',
