  'stl.progressHint': 'Har statement apna alag transaction hai, isliye beech mein vifalta ek vikreta ki dobara koshish hai, poori avadhi ki nahin. Isi wajah se yahan ginti dikhti hai, "sab ek saath" ka daava nahin: ek lakh vikreta ka ek hi transaction kisi bhi database se maangna theek nahin.',
