  'stl.deduction.buyer': 'Commission aur tax ₹0 dikhte hain kyunki aapki sanstha KHARIDAARON se leti hai, vikreta se nahin — isliye vikreta apna poora kul rakhta hai. Column isliye hain ki vikreta-paksh sanstha ko inmein asli katautiyan dikhengi.',
  'stl.deduction.seller': 'Aapki sanstha VIKRETA se leti hai, isliye har vikreta ke kul se kati commission aur tax in columns mein dikhte hain.',
  'stl.deduction.noRule': 'Aapki sanstha ke liye koi sakriya commission niyam nahin mila, isliye ye column ₹0 dikhate hain kyunki kuch tay nahin hua — isliye NAHIN ki kharidaar bharte hain. Ye alag baatein hain, aur cycle band karne se pehle ise set karna chahiye.',
  'stl.legacyDaily': 'Aapke {count} statement raat ke job ne DAINIK dastavez ke roop mein banaye the, jab cycle mojood hi nahin thi. Unhe waisa hi dikhaya gaya hai, cycle statement ka naam nahin diya gaya.',
