  'stl.orgStatementTitle': 'Sanstha ka maheene ka statement',
  'stl.orgStatementDerived': 'Yeh statement har baar aapke append-only ledger se BANAYA jaata hai — shuruaati balance, prakaar se halchal, antim balance — aur agar teenon mein tal-mel na ho to jaari hi nahin hota. Iski koi statement sankhya nahin, kyunki yeh rakhi hui copy nahin hai: jiske paas wahi ledger rows hain wah ise theek waisa hi bana sakta hai, jo file mein rakhi PDF se majboot guarantee hai — kyunki us PDF ko ledger baad mein galat bhi kar sakta hai.',
